const LIMB_MAX_HP = { head: 30, leftArm: 15, rightArm: 15, chest: 50, abdomen: 25, crotch: 15, leftLeg: 20, rightLeg: 20 };
// Limb target area weights for size-weighted random (chest/abdomen largest; used when picking one limb from a pool)
const LIMB_TARGET_WEIGHT = { head: 12, chest: 50, abdomen: 25, leftArm: 10, rightArm: 10, leftLeg: 15, rightLeg: 15, crotch: 8 };
// Melee sticky targeting: attacker picks one zone and keeps hitting that zone (upper/middle/lower)
const MELEE_TARGET_ZONES = {
    upper: ['head', 'leftArm', 'rightArm', 'chest'],
    middle: ['chest', 'abdomen', 'crotch'],
    lower: ['leftLeg', 'rightLeg', 'abdomen', 'crotch']
};
// Probability (out of 100) that melee attacker picks each zone: upper 60%, middle 30%, lower 10%
const MELEE_ZONE_WEIGHTS = { upper: 60, middle: 30, lower: 10 };
// Phase 2: Stance-based limb pools — upright = arms/chest/head, on-all-fours = legs/abdomen
const MELEE_LIMB_POOLS = {
    upright: ['leftArm', 'rightArm', 'chest', 'head'],
    onAllFours: ['leftLeg', 'rightLeg', 'abdomen']
};
// enemyType → stance (upright = walker/bandit/humanoid, onAllFours = leaper/crawler)
const MELEE_STANCE_BY_ENEMY = { walker: 'upright', bandit: 'upright', leaper: 'onAllFours', spitter: 'upright', exploder: 'upright', boss: 'upright', necromancer: 'upright' };
// Phase 4: Ranged limb selection by distance. close = upper/head, medium = torso, far = legs
const RANGED_CLOSE_MAX = 100;
const RANGED_MEDIUM_MAX = 250;
const RANGED_LIMB_BANDS = {
    close: ['head', 'chest', 'leftArm', 'rightArm'],
    medium: ['chest', 'abdomen'],
    far: ['leftLeg', 'rightLeg']
};
// Major bleed moves to this limb when current limb is blacked (chest has no entry = stops there)
// Major bleed damage tick propagates toward chest: leg → crotch → abdomen → chest (chain at most 4 limbs / 3 steps)
const MAJOR_BLEED_PROPAGATION = { head: 'chest', leftArm: 'chest', rightArm: 'chest', abdomen: 'chest', crotch: 'abdomen', leftLeg: 'crotch', rightLeg: 'crotch' };
const LIMB_EFFECT_LABELS = { minor_bleed: 'Minor bleed', major_bleed: 'Major bleed', break: 'Break', trauma: 'Trauma' };
// Phase 3: Base outcome table (cumulative %). One roll per hit in single-limb path.
const LIMB_OUTCOME_TABLE = { damage_only: 82, minor_bleed: 10, major_bleed: 5, break: 2.5, black: 0.5 };
// Phase 5: Consecutive-hit escalation. +pct to effect outcomes per hit, cap; timeout resets count.
const ESCALATION_PCT_PER_HIT = 5;
const ESCALATION_CAP_PCT = 25;
const ESCALATION_TIMEOUT_MS = 15000;
const ESCALATION_EFFECT_TOTAL = 10 + 5 + 2.5 + 0.5; // sum of minor_bleed, major_bleed, break, black
// Phase 6: Per-enemy outcome modifiers (additive % shifted from damage_only into effect)
const ENEMY_OUTCOME_MODIFIERS = {
    leaper: { breakBonus: 5 },
    spitter: { blackBonus: 3 },
    exploder: { majorBleedBonus: 3 },
    boss: { blackBonus: 2, breakBonus: 3 }
};
/** Apply per-enemy modifiers to outcome table. mods = { breakBonus, blackBonus, minorBleedBonus, majorBleedBonus }. */
function outcomeTableWithEnemyModifiers(table, enemyType) {
    const mods = enemyType && ENEMY_OUTCOME_MODIFIERS[enemyType];
    if (!mods) return table;
    let shift = 0;
    const out = { ...table };
    if (mods.minorBleedBonus) { out.minor_bleed = (out.minor_bleed || 0) + mods.minorBleedBonus; shift += mods.minorBleedBonus; }
    if (mods.majorBleedBonus) { out.major_bleed = (out.major_bleed || 0) + mods.majorBleedBonus; shift += mods.majorBleedBonus; }
    if (mods.breakBonus) { out.break = (out.break || 0) + mods.breakBonus; shift += mods.breakBonus; }
    if (mods.blackBonus) { out.black = (out.black || 0) + mods.blackBonus; shift += mods.blackBonus; }
    if (shift > 0) out.damage_only = Math.max(0, (out.damage_only != null ? out.damage_only : 82) - shift);
    return out;
}
/** Build outcome table with escalation: shift shiftPct from damage_only into effects (proportional). */
function outcomeTableWithEscalation(baseTable, hitCount) {
    const shiftPct = Math.min(hitCount * ESCALATION_PCT_PER_HIT, ESCALATION_CAP_PCT);
    if (shiftPct <= 0) return baseTable;
    const d = baseTable.damage_only != null ? baseTable.damage_only : 82;
    const out = { ...baseTable };
    out.damage_only = Math.max(0, d - shiftPct);
    const ratio = shiftPct / ESCALATION_EFFECT_TOTAL;
    if (out.minor_bleed != null) out.minor_bleed = out.minor_bleed + 10 * ratio;
    if (out.major_bleed != null) out.major_bleed = out.major_bleed + 5 * ratio;
    if (out.break != null) out.break = out.break + 2.5 * ratio;
    if (out.black != null) out.black = out.black + 0.5 * ratio;
    return out;
}
/** Roll one outcome from the table. table = { outcomeId: cumulativePercent, ... }. Returns outcome id string. */
function rollOutcome(table) {
    const entries = Object.entries(table);
    let total = 0;
    for (const [, pct] of entries) total += pct;
    let r = Math.random() * total;
    for (const [outcome, pct] of entries) {
        r -= pct;
        if (r <= 0) return outcome;
    }
    return entries[0][0];
}
/** Human-readable limb name for damage log */
const LIMB_DISPLAY_NAMES = { head: 'Head', leftArm: 'L.Arm', rightArm: 'R.Arm', chest: 'Chest', abdomen: 'Abdomen', crotch: 'Crotch', leftLeg: 'L.Leg', rightLeg: 'R.Leg', hp: 'HP' };
function getDefaultLimbHp() {
    const o = {}; for (const k of Object.keys(LIMB_MAX_HP)) o[k] = { hp: LIMB_MAX_HP[k], maxHp: LIMB_MAX_HP[k], status: '', effects: [] }; return o;
}
function limbEffectsToStatusString(effects) {
    if (!Array.isArray(effects) || effects.length === 0) return '';
    return effects.map(e => LIMB_EFFECT_LABELS[e] || e).join(', ');
}
function sumLimbHp(limbHp) {
    if (!limbHp) return 0;
    return Object.keys(limbHp).reduce((s, k) => s + (limbHp[k].hp || 0), 0);
}
function sumLimbMaxHp(limbHp) {
    if (!limbHp) return 0;
    return Object.keys(limbHp).reduce((s, k) => s + (limbHp[k].maxHp || 0), 0);
}
/** Pick one limb id by size-weighted random. limbIds = array of limb ids, or null/undefined = all limbs from LIMB_MAX_HP. */
function pickOneLimbByWeight(limbIds) {
    const ids = limbIds && limbIds.length > 0 ? limbIds : Object.keys(LIMB_MAX_HP);
    let total = 0;
    for (const id of ids) {
        const w = LIMB_TARGET_WEIGHT[id];
        if (w != null && w > 0) total += w;
    }
    if (total <= 0) return ids[Math.floor(Math.random() * ids.length)];
    let r = Math.random() * total;
    for (const id of ids) {
        const w = LIMB_TARGET_WEIGHT[id];
        if (w != null && w > 0) {
            r -= w;
            if (r <= 0) return id;
        }
    }
    return ids[ids.length - 1];
}
function limbHasBreak(limbHp, limbId) {
    return limbHp && limbHp[limbId] && Array.isArray(limbHp[limbId].effects) && limbHp[limbId].effects.includes('break');
}

function limbHasBleedEffect(limbHp, effectId) {
    if (!limbHp) return false;
    return Object.keys(limbHp).some(id => {
        const e = limbHp[id] && limbHp[id].effects;
        return Array.isArray(e) && e.includes(effectId);
    });
}

function hasAnyBleed(limbHp) {
    return limbHasBleedEffect(limbHp, 'minor_bleed') || limbHasBleedEffect(limbHp, 'major_bleed');
}

/** Ensure blood/infection fields exist on loaded/legacy saves. */
function ensureLimbVisStats(stats) {
    if (!stats) return stats;
    const maxB = (CONFIG.LIMB_VIS && CONFIG.LIMB_VIS.BLOOD_MAX) || 100;
    if (stats.maxBlood == null || stats.maxBlood <= 0) stats.maxBlood = maxB;
    if (stats.blood == null || stats.blood < 0) stats.blood = stats.maxBlood;
    if (stats.infection == null || stats.infection < 0) stats.infection = 0;
    if (stats.infection > 100) stats.infection = 100;
    return stats;
}

/** Clear infection on stats. Returns true if there was infection to clear. */
function cureInfectionOnStats(stats) {
    ensureLimbVisStats(stats);
    if ((stats.infection || 0) <= 0) return false;
    stats.infection = 0;
    return true;
}

/** Count item labels in grids/pockets/consumables for death-recap diffs. */
function countCarriedItemLabels(stats) {
    const counts = Object.create(null);
    const bump = (label, n) => {
        if (!label) return;
        counts[label] = (counts[label] || 0) + (n || 1);
    };
    const addGrid = (grid) => {
        (grid && grid.items ? grid.items : []).forEach(p => {
            const cfg = getInventoryItemConfig(p.itemId);
            bump((cfg && cfg.label) ? cfg.label : p.itemId, p.count || 1);
        });
    };
    if (!stats) return counts;
    addGrid(stats.backpack);
    addGrid(stats.rigGrid);
    addGrid(stats.medBagGrid);
    addGrid(stats.secureContainerGrid);
    if (Array.isArray(stats.pockets)) {
        stats.pockets.forEach(pocket => {
            (pocket || []).forEach(cell => {
                if (!cell || !cell.itemId) return;
                if (cell._spansFrom) return;
                const cfg = getInventoryItemConfig(cell.itemId);
                bump((cfg && cfg.label) ? cfg.label : cell.itemId, cell.count || 1);
            });
        });
    }
    (stats.consumables || []).forEach(id => {
        if (!id) return;
        const c = CONFIG.CONSUMABLES && CONFIG.CONSUMABLES[id];
        bump(c ? c.name : id, 1);
    });
    return counts;
}

/** Labels for items present in `current` but not in `baseline` (mid-raid loot lost on death). */
function diffLostItemLabels(currentStats, baselineStats) {
    const cur = countCarriedItemLabels(currentStats);
    const base = countCarriedItemLabels(baselineStats);
    const lost = [];
    Object.keys(cur).forEach(label => {
        const n = cur[label] - (base[label] || 0);
        if (n > 0) lost.push(n > 1 ? `${label} x${n}` : label);
    });
    return lost;
}

